function validate([k, operations]) {
  if (!Number.isInteger(k) || k < 1 || k > 1e14) return 'k must be a whole number from 1 to 10^14.';
  if (operations.length < 1 || operations.length > 100) return 'operations needs 1 to 100 entries.';
  if (operations.some(op => op !== 0 && op !== 1)) return 'Each operation is 0 or 1.';
  if (2 ** operations.length < k) return 'The final word must have at least k letters: 2^operations.length must be at least k.';
  return null;
}

