function kthCharacter(k, operations) {
  let position = k - 1;
  let shifts = 0;
  for (let i = 0; position > 0; i++) {
    if (position % 2 === 1) {
      shifts += operations[i];
    }
    position = Math.floor(position / 2);
  }
  return String.fromCharCode(97 + (shifts % 26));
}

brute:
function kthCharacter(k, operations) {
  // Replay the game backwards: before operation i the word has 2^i letters, and a letter
  // in the block that operation i added is the letter 2^i places earlier, maybe shifted.
  let shifts = 0;
  let place = k;
  for (let i = operations.length - 1; i >= 0; i--) {
    const half = 2 ** i;
    if (place > half) {
      place -= half;
      if (operations[i] === 1) shifts++;
    }
  }
  return 'abcdefghijklmnopqrstuvwxyz'[shifts % 26];
}

generator:
function generate(rand, size) {
  const wide = size === 'large' || rand() < 0.25;
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : wide ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 10);
  const style = rand();
  const operations = Array.from({ length: n }, () => style < 0.15 ? 0 : style < 0.3 ? 1 : rand() < 0.5 ? 0 : 1);
  const limit = Math.min(2 ** n, 1e14);
  const k = size === 'large' ? 1e14 - Math.floor(rand() * 1e13) : 1 + Math.floor(rand() * limit);
  return [k, operations];
}
